session_start();header('Content-Type: application/json; charset=utf-8');require_once __DIR__.'/conexion.php';$data=json_decode(file_get_contents('php://input'),true)??[];$code=strtoupper(trim($data['codigo']??''));$subtotal=(float)($data['subtotal']??0);if(!$code||$subtotal<0){http_response_code(422);echo json_encode(['success'=>false,'message'=>'Código o subtotal inválido.']);exit;}$q=$pdo->prepare("SELECT * FROM cupones WHERE codigo=? AND activo=1 AND (inicia_en IS NULL OR inicia_en<=NOW()) AND (vence_en IS NULL OR vence_en>=NOW()) AND (usos_maximos IS NULL OR usos_actuales<usos_maximos) LIMIT 1");$q->execute([$code]);$c=$q->fetch();if(!$c||$subtotal<(float)$c['minimo_compra']){http_response_code(400);echo json_encode(['success'=>false,'message'=>'Cupón inválido, vencido o no cumple la compra mínima.']);exit;}$discount=$c['tipo']==='porcentaje'?$subtotal*((float)$c['valor']/100):(float)$c['valor'];$discount=min($subtotal,$discount);echo json_encode(['success'=>true,'codigo'=>$code,'descuento'=>round($discount,2),'message'=>'Cupón aplicado.']);
